    #[test]
    fn item_catalog_is_complete_contiguous_and_unique() {
        assert_eq!(VANILLA_ITEM_TYPES.len(), 1506);
        let mut resources = HashSet::new();
        for (id, entry) in VANILLA_ITEM_TYPES.iter().enumerate() {
            assert_eq!(entry.id, id as i32);
            assert!(entry.resource_id.starts_with("minecraft:"));
            assert!(resources.insert(entry.resource_id));
        }
    }

