    #[test]
    fn tool_use_on_consumer_uses_generated_catalogs() {
        let crates = Path::new(env!("CARGO_MANIFEST_DIR")).parent().unwrap();
        let path = crates.join("bbb-world/src/client/inventory/use_prediction.rs");
        let source = fs::read_to_string(&path).unwrap();
        let production = source.split("#[cfg(test)]").next().unwrap();
        for catalog in [
            "VANILLA_AXE_STRIPPABLES",
            "VANILLA_AXE_SCRAPEABLES",
            "VANILLA_AXE_WAX_OFF",
            "VANILLA_HONEYCOMB_WAXABLES",
            "VANILLA_HOE_TILLABLES",
            "VANILLA_SHOVEL_FLATTENABLES",
        ] {
            assert!(
                production.contains(catalog),
                "{} missing generated {catalog}",
                path.display()
            );
        }
        let mut block_ids = HashSet::new();
        for transform in VANILLA_AXE_STRIPPABLES
            .iter()
            .chain(VANILLA_AXE_SCRAPEABLES)
            .chain(VANILLA_AXE_WAX_OFF)
            .chain(VANILLA_HONEYCOMB_WAXABLES)
            .chain(VANILLA_SHOVEL_FLATTENABLES)
        {
            block_ids.insert(transform.source_block_type_id);
            block_ids.insert(transform.target_block_type_id);
        }
        for tillable in VANILLA_HOE_TILLABLES {
            block_ids.insert(tillable.transform.source_block_type_id);
            block_ids.insert(tillable.transform.target_block_type_id);
        }
        for block_id in block_ids {
            let resource_id = crate::block_types::vanilla_block_type(block_id)
                .unwrap()
                .resource_id;
            let literal = format!("\"{resource_id}\"");
            assert!(
                !production.contains(&literal),
                "{} restored hand-written {literal}",
                path.display()
            );
        }
    }

