    #[test]
    fn item_stack_size_consumers_use_generated_constants() {
        assert_eq!(VANILLA_ITEM_DEFAULT_MAX_STACK_SIZE, 64);
        assert_eq!(VANILLA_ITEM_ABSOLUTE_MAX_STACK_SIZE, 99);
        let crates = Path::new(env!("CARGO_MANIFEST_DIR")).parent().unwrap();
        let sources = [
            crates.join("bbb-world/src/item_profiles.rs"),
            crates.join("bbb-item-model/src/item_runtime/icon_model.rs"),
        ];
        for path in sources {
            let source = fs::read_to_string(&path).unwrap();
            assert!(
                source.contains("VANILLA_ITEM_DEFAULT_MAX_STACK_SIZE"),
                "{} missing generated default stack size",
                path.display()
            );
            assert!(
                source.contains("VANILLA_ITEM_ABSOLUTE_MAX_STACK_SIZE"),
                "{} missing generated absolute stack size",
                path.display()
            );
            for removed in [
                "VANILLA_DEFAULT_MAX_STACK_SIZE",
                "VANILLA_ABSOLUTE_MAX_STACK_SIZE",
            ] {
                assert!(
                    !source.contains(removed),
                    "{} restored removed {removed}",
                    path.display()
                );
            }
        }
        for path in [
            crates.join("bbb-world/src/client/inventory.rs"),
            crates.join("bbb-world/src/client/inventory/merchant.rs"),
            crates.join("bbb-world/src/client/inventory/slot_ops.rs"),
        ] {
            let source = fs::read_to_string(&path).unwrap();
            assert!(
                source.contains("VANILLA_ITEM_DEFAULT_MAX_STACK_SIZE"),
                "{} missing generated default stack size",
                path.display()
            );
            for removed in [
                "VANILLA_DEFAULT_MAX_STACK_SIZE",
                "VANILLA_ABSOLUTE_MAX_STACK_SIZE",
            ] {
                assert!(
                    !source.contains(removed),
                    "{} restored removed {removed}",
                    path.display()
                );
            }
        }
    }

